#!/usr/bin/env python3
"""Search gadgets.txt (custom finder output) for useful patterns."""
import re, sys

gadgets = []
for line in open('gadgets_custom.txt'):
    line = line.rstrip('\n')
    if ' : ' in line:
        a, t = line.split(' : ', 1)
        gadgets.append((int(a, 16), t.strip()))

def find(pat, limit=15):
    rx = re.compile(pat)
    out = []
    for a, t in gadgets:
        if rx.match(t):
            out.append((a, t))
    return out[:limit]

pats = sys.argv[1:]
for p in pats:
    print('### %s' % p)
    for a, t in find(p):
        print('  %#x : %s' % (a, t))

